@startuml
class Game {
  +id : long
}
class Player {
  +id : long
}
class Deck {
  +id : long
}
class Card {
  +id : long
  +compareHeight(other : Card) : string
}
class ScoringTable {
  +id : long
}
class Round {
  +id : long
  +pointValue : int
}
class JackRound {
}
class SoloRound {
  +soloType : SoloType
}
class MandatorySoloRound extends SoloRound {
}
enum SoloType {
  TRUMP
  JACK
  QUEEN
}
enum Suit {
  DIAMONDS
  HEARTS
  SPADES
  CLUBS
}

Game "1" *-- "4" Player
Game "1" *-- "1" Deck
Game "1" *-- "1" ScoringTable
Deck "1" *-- "0..48" Card
ScoringTable "1" *-- "1..*" Round
Round "1" -- "*" Player : winning players
Round <|-- JackRound
Round <|-- SoloRound
SoloRound "1" -- "1" Player : solo player

Card --> Suit
@enduml

